import React, { useCallback } from 'react';
import styled from 'styled-components';
import { ClickableButtonName } from '../../types';
import type { ApplicationVersionSubmission } from '@getvim-os/types';
export const NO_PHI_APPS = new Set([
  '8bfd8ae3-e933-4685-b09e-d6deffdf3b5a', // good rx dev
  '800f69b1-a5dc-49a6-9e65-ee7a4981c648', // good rx prod
]);

interface ApplicationPolicyProps {
  appId: string;
  appName: string;
  appAccountName: string;
  isCoreApp?: boolean;
  legalDocs: NonNullable<ApplicationVersionSubmission['appStoreListing']>['legal'];
  onClick: (buttonName: ClickableButtonName) => void;
}

const ApplicationPolicy: React.FC<ApplicationPolicyProps> = ({
  appId,
  appName,
  appAccountName,
  isCoreApp,
  legalDocs,
  onClick,
}) => {
  const noPhis = NO_PHI_APPS.has(appId);

  const privacyPolicyClicked = useCallback(() => {
    onClick(ClickableButtonName.PRIVACY_POLICY);
  }, [onClick]);

  const termsOfServiceClicked = useCallback(() => {
    onClick(ClickableButtonName.TERMS_OF_SERVICE);
  }, [onClick]);

  const baaClicked = useCallback(() => {
    onClick(ClickableButtonName.BAA);
  }, [onClick]);

  if (!legalDocs) {
    return null;
  }

  const isOnlineBAA =
    legalDocs.baaMetadata?.baaLinkType !== 'private' && Boolean(legalDocs.baaLink);

  const termsLink = (
    <PolicyLink onClick={termsOfServiceClicked} href={legalDocs.termsOfServiceLink}>
      {'Terms'}
    </PolicyLink>
  );

  const privacyPolicyLink = (
    <PolicyLink onClick={privacyPolicyClicked} href={legalDocs.privacyLink}>
      {'Privacy Policy'}
    </PolicyLink>
  );

  const baaLink = (
    <PolicyLink onClick={baaClicked} href={legalDocs.baaLink}>
      {'BAA'}
    </PolicyLink>
  );

  const appNameBold = <Bold>{appName}</Bold>;
  const appAccountNameBold = <Bold>{appAccountName}</Bold>;

  const coreAppText = isCoreApp && (
    <>
      The use of {appNameBold} is subject to the application {termsLink}
    </>
  );

  const appTextOnlineBAA = !isCoreApp && isOnlineBAA && (
    <>
      {appNameBold} is provided by {appAccountNameBold} and is subject to the {appName} {termsLink}{' '}
      and {privacyPolicyLink}. By using this app, you instruct Vim to disclose EHR data (including
      PHI) to {appAccountNameBold}. Such disclosure and use of data are solely governed by the{' '}
      {appName} {baaLink}.
    </>
  );

  const appTextOfflineBAA = !isCoreApp && !isOnlineBAA && (
    <>
      {appNameBold} is provided by {appAccountNameBold} and is subject to the {appName} {termsLink}{' '}
      and {privacyPolicyLink}. You instruct Vim to disclose your EHR data to {appAccountNameBold}.
      To the extent such disclosure includes PHI, you represent that it is necessary for treatment,
      payment, or healthcare operations, and, if applicable, you will enter into a Business
      Associate Agreement (BAA) with {appAccountNameBold}.
    </>
  );

  const noPhiText = noPhis && (
    <>
      {appNameBold} is provided by {appAccountNameBold} and is subject to the {appAccountNameBold}{' '}
      {termsLink} and {privacyPolicyLink}. This application does not subscribe to PHI through Vim
      today, and therefore is not covered under your BAA with Vim. In the event that you share PHI
      with the application or vendor, such disclosure shall be subject to the vendor's Terms and
      Privacy Policy.
    </>
  );

  return (
    <PolicyNotice data-testid={`application-policy-${appId}`}>
      {noPhiText || coreAppText || appTextOnlineBAA || appTextOfflineBAA}
    </PolicyNotice>
  );
};

const PolicyNotice = styled.div`
  background-color: #10abe433;
  padding: 7px 40px;
  border-radius: 14px;
  font-size: 11px;
  text-align: center;
  line-height: 16px;
  font-weight: 400;

  @media (max-width: 900px) {
    padding: 7px 10px;
  }
`;

const PolicyLink = styled.a.attrs((props) => ({
  href: props.href || undefined,
  target: '_blank',
  rel: 'noopener noreferrer',
  onclick: props.onClick,
}))`
  text-decoration: underline;
  font-weight: 700;
  cursor: pointer;
`;

const Bold = styled.strong`
  font-weight: 700;
`;

export default ApplicationPolicy;
